package main

import (
 "encoding/xml"
 "fmt"
 "os"
 "strings"
)
func main(){
 inputs:=[]string{
  `<ns:root xmlns:ns="http://example.com"><ns:child attr="1" ns:a="2">v</ns:child></ns:root>`,
  `<a><b></a></b>`,
  `<r><br><hr><img src="x"></r>`,
  `<r attr>x</r>`,
  `<r>&unknown;</r>`,
  `<r attr=unq>x</r>`,
  `<a><b>1</a><c>2</c>`,
  `<!DOCTYPE root [ <!ELEMENT root ANY> ]><r>x</r>`,
 }
 strict:=os.Args[1]=="strict"
 raw:=os.Args[2]=="raw"
 fmt.Println("strict",strict,"raw",raw)
 for _,inp:=range inputs{
   fmt.Printf("\nIN %q\n", inp)
   d:=xml.NewDecoder(strings.NewReader(inp)); d.Strict=strict
   for {
     var t xml.Token; var err error
     if raw { t,err=d.RawToken() } else { t,err=d.Token() }
     fmt.Printf(" tok=%#v err=%v\n", t,err)
     if err!=nil {break}
   }
 }
}
GO
cd /tmp/gotest && go mod init test >/dev/null 2>&1; go run main.go strict token > /tmp/st.txt; go run main.go nonstrict token > /tmp/nt.txt; go run main.go strict raw > /tmp/sr.txt; go run main.go nonstrict raw > /tmp/nr.txt
for f in /tmp/st.txt /tmp/nt.txt /tmp/sr.txt /tmp/nr.txt; do echo "==== $f"; cat "$f"; done"}

