{"command":"mkdir -p /tmp/charsettest && cat >/tmp/charsettest/main.go <<'GO'
package main
import("encoding/xml";"fmt";"io";"os";"golang.org/x/text/encoding/ianaindex")
func reader(charset string,input io.Reader)(io.Reader,error){
 var enc interface{NewDecoder() *struct{}}
 _ = enc
 var e interface{}
 _=e
 var encoding interface{}
 _=encoding
 // use mode
 mode:=os.Args[1]
 var enco interface{ NewDecoder() interface{} }
 _=enco
 var err error
 var encObj interface{}
 _=encObj
 if mode=="mime" {
   enc2, err2 := ianaindex.MIME.Encoding(charset); err=err2
   fmt.Fprintf(os.Stderr,"charset %q enc=%#v err=%v\n",charset,enc2,err)
   if err!=nil {return nil,err}
   if enc2==nil {return nil,nil}
   return enc2.NewDecoder().Reader(input),nil
 } else {
   enc2, err2 := ianaindex.IANA.Encoding(charset); err=err2
   fmt.Fprintf(os.Stderr,"charset %q enc=%#v err=%v\n",charset,enc2,err)
   if err!=nil {return nil,err}
   if enc2==nil {return nil,nil}
   return enc2.NewDecoder().Reader(input),nil
 }
}
func main(){
 d:=xml.NewDecoder(os.Stdin); d.Strict=false; d.CharsetReader=reader
 for{ t,err:=d.Token(); fmt.Fprintf(os.Stdout,"tok=%#v err=%v\n",t,err); if err!=nil{break}}
}
GO
