package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"syscall"
	"unsafe"

	"github.com/spf13/pflag"
)

const versionText = "xq version 1.4.0\n"
const helpText = `Command-line XML and HTML beautifier and content extractor

Usage:
  xq [flags]

Flags:
  -a, --attr string      Extract an attribute value instead of node content for provided CSS query
  -c, --color            Force colorful output
      --compact          Compact JSON output (no indentation)
  -d, --depth int        Maximum nesting depth for JSON output (-1 for unlimited) (default -1)
  -e, --extract string   Extract a single node from XML
  -h, --help             Print this help message
  -m, --html             Use HTML formatter
  -i, --in-place         Format file in place
      --indent int       Use the given number of spaces for indentation (default 2)
  -j, --json             Output the result as JSON
      --no-color         Disable colorful output
  -n, --node             Return the node content instead of text
  -q, --query string     Extract the node(s) using CSS selector
      --tab              Use tabs for indentation
  -v, --version          Print version information
  -x, --xpath string     Extract the node(s) from XML
`

type options struct {
	attr     string
	color    bool
	compact  bool
	depth    int
	extract  string
	help     bool
	html     bool
	inPlace  bool
	indent   int
	json     bool
	noColor  bool
	node     bool
	query    string
	tab      bool
	version  bool
	xpath    string
	args     []string
	colored  bool
	indentStr string
}

func topError(err error) {
	fmt.Fprintf(os.Stderr, "Error: %v\n", err)
	os.Exit(1)
}

func isTerminal(fd uintptr) bool {
	// Linux TCGETS ioctl; enough for the supported test environment.
	var termios [64]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(0x5401), uintptr(unsafe.Pointer(&termios[0])))
	return errno == 0
}

func main() {
	var o options
	fs := pflag.NewFlagSet("xq", pflag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.StringVarP(&o.attr, "attr", "a", "", "Extract an attribute value instead of node content for provided CSS query")
	fs.BoolVarP(&o.color, "color", "c", false, "Force colorful output")
	fs.BoolVar(&o.compact, "compact", false, "Compact JSON output (no indentation)")
	fs.IntVarP(&o.depth, "depth", "d", -1, "Maximum nesting depth for JSON output (-1 for unlimited)")
	fs.StringVarP(&o.extract, "extract", "e", "", "Extract a single node from XML")
	fs.BoolVarP(&o.help, "help", "h", false, "Print this help message")
	fs.BoolVarP(&o.html, "html", "m", false, "Use HTML formatter")
	fs.BoolVarP(&o.inPlace, "in-place", "i", false, "Format file in place")
	fs.IntVar(&o.indent, "indent", 2, "Use the given number of spaces for indentation")
	fs.BoolVarP(&o.json, "json", "j", false, "Output the result as JSON")
	fs.BoolVar(&o.noColor, "no-color", false, "Disable colorful output")
	fs.BoolVarP(&o.node, "node", "n", false, "Return the node content instead of text")
	fs.StringVarP(&o.query, "query", "q", "", "Extract the node(s) using CSS selector")
	fs.BoolVar(&o.tab, "tab", false, "Use tabs for indentation")
	fs.BoolVarP(&o.version, "version", "v", false, "Print version information")
	fs.StringVarP(&o.xpath, "xpath", "x", "", "Extract the node(s) from XML")
	if err := fs.Parse(os.Args[1:]); err != nil {
		topError(err)
	}
	o.args = fs.Args()
	if o.help {
		fmt.Fprint(os.Stdout, helpText)
		return
	}
	if o.version {
		fmt.Fprint(os.Stdout, versionText)
		return
	}
	if o.indent < 0 || o.indent > 8 {
		topError(fmt.Errorf("indent should be between 0-8 spaces"))
	}

	var readers []*bufio.Reader
	var files []*os.File
	if len(o.args) > 0 {
		for _, name := range o.args {
			f, err := os.Open(name)
			if err != nil {
				topError(err)
			}
			files = append(files, f)
			readers = append(readers, bufio.NewReader(f))
		}
	} else {
		readers = append(readers, bufio.NewReader(os.Stdin))
	}

	if o.inPlace && len(o.args) != 1 {
		topError(fmt.Errorf("in-place formatting requires a file path (and only one file path)"))
	}
	if o.attr != "" && o.query == "" {
		topError(fmt.Errorf("query option (-q) is missed for attribute selection"))
	}

	o.colored = o.color || (isTerminal(os.Stdout.Fd()) && !o.noColor)
	if os.Getenv("NO_COLOR") != "" {
		o.colored = false
	}
	if o.inPlace {
		o.colored = false
	}
	o.indentStr = strings.Repeat(" ", o.indent)
	if o.tab {
		o.indentStr = "\t"
	}

	var output io.Writer
	var buffer bytes.Buffer
	var pagerCmd *exec.Cmd
	var pagerPipe io.WriteCloser
	if o.inPlace {
		output = &buffer
	} else if os.Getenv("PAGER") == "less" {
		pagerCmd = exec.Command("less", "--quit-if-one-screen", "--no-init", "--RAW-CONTROL-CHARS")
		pagerCmd.Stdout = os.Stdout
		pipe, err := pagerCmd.StdinPipe()
		if err != nil {
			topError(err)
		}
		if err := pagerCmd.Start(); err != nil {
			topError(err)
		}
		pagerPipe = pipe
		output = pipe
	} else {
		output = os.Stdout
	}

	var lastErr error
	for _, r := range readers {
		lastErr = process(r, output, &o)
	}
	for _, f := range files {
		f.Close()
	}

	var pagerErr error
	if pagerCmd != nil {
		pagerPipe.Close()
		pagerErr = pagerCmd.Wait()
	}
	if lastErr != nil {
		fmt.Fprintf(os.Stdout, "Error: %v\n", lastErr)
		os.Exit(1)
	}
	if pagerErr != nil {
		topError(pagerErr)
	}
	if o.inPlace {
		if err := os.WriteFile(o.args[0], buffer.Bytes(), 0644); err != nil {
			topError(err)
		}
	}
}

type contentType int

const (
	contentXML contentType = iota
	contentHTML
	contentJSON
	contentUnknown
)

func detectContentType(r *bufio.Reader) contentType {
	b, _ := r.Peek(10)
	if len(b) == 0 {
		return contentUnknown
	}
	s := strings.ToLower(string(b))
	if strings.Contains(s, "{") || strings.Contains(s, "[") {
		return contentJSON
	}
	if strings.Contains(s, "html") || strings.Contains(s, "<body") || strings.Contains(s, "<!d") {
		return contentHTML
	}
	return contentXML
}

func process(r *bufio.Reader, w io.Writer, o *options) error {
	if o.xpath != "" {
		return extractXPath(r, w, o.xpath, false, o)
	}
	if o.extract != "" {
		return extractXPath(r, w, o.extract, true, o)
	}
	if o.query != "" {
		return extractCSS(r, w, o)
	}
	if o.json {
		return outputJSON(r, w, o)
	}
	if o.html {
		return formatHTML(r, w, o.indentStr, o.colored)
	}
	switch ct := detectContentType(r); ct {
	case contentXML:
		return formatXML(r, w, o.indentStr, o.colored)
	case contentHTML:
		return formatHTML(r, w, o.indentStr, o.colored)
	case contentJSON:
		return formatJSON(r, w, o.indentStr, o.colored)
	default:
		return fmt.Errorf("unknown content type: %d", int(ct))
	}
}
EOF
