package main

import (
	"encoding/json"
	"encoding/xml"
	"fmt"
	"io"
	"strings"

	"golang.org/x/net/html"
	"golang.org/x/text/encoding/ianaindex"
)

func getCharsetReader(charset string, input io.Reader) (io.Reader, error) {
	if strings.EqualFold(charset, "UTF-16") {
		return input, nil
	}
	enc, err := ianaindex.MIME.Encoding(charset)
	if err != nil {
		return nil, err
	}
	return enc.NewDecoder().Reader(input), nil
}

type simpleFormatter struct {
	w       io.Writer
	indent  string
	colored bool
}

func (f *simpleFormatter) write(s string) {
	_, _ = io.WriteString(f.w, s)
}
func (f *simpleFormatter) indentStr(depth int) string {
	if depth <= 0 {
		return ""
	}
	return strings.Repeat(f.indent, depth)
}
func (f *simpleFormatter) yellow(s string) string {
	if !f.colored {
		return s
	}
	return "\x1b[33m" + s + "\x1b[0m"
}
func (f *simpleFormatter) green(s string) string {
	if !f.colored {
		return s
	}
	return "\x1b[32m" + s + "\x1b[0m"
}
func (f *simpleFormatter) blue(s string) string {
	if !f.colored {
		return s
	}
	return "\x1b[94m" + s + "\x1b[0m"
}

const (
	prevNone = iota
	prevStart
	prevEnd
	prevText
	prevSelfClosing
)

func xmlName(name xml.Name, ns map[string]string) string {
	if name.Space == "" {
		return name.Local
	}
	if prefix, ok := ns[name.Space]; ok {
		return prefix + ":" + name.Local
	}
	return name.Space + ":" + name.Local
}

func formatXML(r io.Reader, w io.Writer, indent string, colored bool) error {
	f := &simpleFormatter{w: w, indent: indent, colored: colored}
	dec := xml.NewDecoder(r)
	dec.Strict = false
	dec.CharsetReader = getCharsetReader
	depth := 0
	tagOpened := false
	prev := prevNone
	ns := map[string]string{"http://www.w3.org/XML/1998/namespace": "xml"}
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			f.write("\n")
			return nil
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			for _, a := range t.Attr {
				if a.Name.Space == "xmlns" {
					if _, ok := ns[a.Value]; !ok {
						ns[a.Value] = a.Name.Local
					}
				}
			}
			if tagOpened {
				f.write(f.yellow(">"))
				tagOpened = false
			}
			if depth > 0 {
				f.write("\n" + f.indentStr(depth))
			}
			f.write(f.yellow("<" + xmlName(t.Name, ns)))
			for _, a := range t.Attr {
				f.write(" " + xmlName(a.Name, ns))
				f.write(f.green("=\"" + xml.EscapeString(a.Value) + "\""))
			}
			depth++
			tagOpened = true
			prev = prevStart
		case xml.EndElement:
			depth--
			if prev == prevStart {
				f.write(f.yellow("/>"))
			} else {
				if prev == prevEnd {
					f.write("\n" + f.indentStr(depth))
				}
				f.write(f.yellow("</" + xmlName(t.Name, ns) + ">"))
			}
			tagOpened = false
			prev = prevEnd
		case xml.CharData:
			s := string(t)
			if strings.TrimSpace(s) == "" {
				continue
			}
			if tagOpened {
				f.write(f.yellow(">"))
				tagOpened = false
			}
			s = strings.TrimRight(s, " ")
			if strings.ContainsAny(s, "<&") {
				f.write("<![CDATA[" + s + "]]>")
			} else {
				f.write(s)
			}
			prev = prevText
		case xml.Comment:
			if tagOpened {
				f.write(f.yellow(">"))
				tagOpened = false
			}
			if depth > 0 && prev != prevText {
				f.write("\n" + f.indentStr(depth))
			}
			f.write(f.blue("<!--"))
			f.write(f.blue(string(t)))
			f.write(f.blue("-->"))
			if depth == 0 {
				f.write("\n")
			}
		case xml.ProcInst:
			f.write(f.yellow("<?"))
			f.write(t.Target)
			parts := strings.Split(string(t.Inst), " ")
			for _, part := range parts {
				kv := strings.SplitN(part, "=", 2)
				f.write(" " + kv[0])
				f.write(f.green("=" + kv[1]))
			}
			f.write(f.yellow("?>"))
			f.write("\n")
		case xml.Directive:
			f.write(f.yellow("<!"))
			f.write(string(t))
			f.write(f.yellow(">"))
			f.write("\n")
			if depth > 0 {
				f.write(f.indentStr(depth))
			}
		}
	}
}

var htmlVoidTags = map[string]bool{
	"area": true, "base": true, "br": true, "col": true, "embed": true,
	"hr": true, "img": true, "input": true, "keygen": true, "link": true,
	"meta": true, "param": true, "source": true, "track": true, "wbr": true,
}

func formatHTML(r io.Reader, w io.Writer, indent string, colored bool) error {
	f := &simpleFormatter{w: w, indent: indent, colored: colored}
	z := html.NewTokenizer(r)
	depth := 0
	prev := prevNone
	writeTag := func(tok html.Token, selfClosing bool) {
		if depth > 0 {
			f.write("\n" + f.indentStr(depth))
		}
		f.write(f.yellow("<" + tok.Data))
		for _, a := range tok.Attr {
			f.write(" " + a.Key)
			f.write(f.green("=\"" + xml.EscapeString(a.Val) + "\""))
		}
		if selfClosing {
			f.write(f.yellow("/>"))
		} else {
			f.write(f.yellow(">"))
		}
	}
	for {
		tt := z.Next()
		switch tt {
		case html.ErrorToken:
			if z.Err() == io.EOF {
				f.write("\n")
				return nil
			}
			return z.Err()
		case html.StartTagToken:
			tok := z.Token()
			if htmlVoidTags[tok.Data] {
				writeTag(tok, true)
				prev = prevSelfClosing
			} else {
				writeTag(tok, false)
				depth++
				prev = prevStart
			}
		case html.SelfClosingTagToken:
			tok := z.Token()
			writeTag(tok, true)
			prev = prevSelfClosing
		case html.EndTagToken:
			tok := z.Token()
			depth--
			if prev == prevEnd {
				f.write("\n" + f.indentStr(depth))
			}
			f.write(f.yellow("</" + tok.Data + ">"))
			prev = prevEnd
		case html.TextToken:
			text := string(z.Text())
			if strings.TrimSpace(text) == "" {
				continue
			}
			f.write(strings.TrimRight(text, " "))
			prev = prevText
		case html.CommentToken:
			if depth > 0 && prev != prevText {
				f.write("\n" + f.indentStr(depth))
			}
			f.write(f.blue(string(z.Raw())))
			if depth == 0 {
				f.write("\n")
			}
		case html.DoctypeToken:
			tok := z.Token()
			f.write(f.yellow("<!doctype "))
			f.write(tok.Data)
			f.write(f.yellow(">"))
			f.write("\n")
		}
	}
}

// ---- JSON ----

type jsonCtx struct {
	object int // 1 object, 2 array
	expectKey bool
}

func formatJSON(r io.Reader, w io.Writer, indent string, colored bool) error {
	f := &simpleFormatter{w: w, indent: indent, colored: colored}
	dec := json.NewDecoder(r)
	dec.UseNumber()
	var stack []*jsonCtx
	afterValue := func() {
		if len(stack) == 0 {
			return
		}
		top := stack[len(stack)-1]
		if top.object == 1 {
			top.expectKey = true
		}
		if dec.More() {
			f.write(",")
			if indent != "" {
				f.write("\n" + f.indentStr(len(stack)))
			}
		}
	}
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			f.write("\n")
			return nil
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{', '[':
				f.write(f.yellow(string(t)))
				ctx := &jsonCtx{object: 2}
				if t == '{' {
					ctx.object = 1
					ctx.expectKey = true
				}
				stack = append(stack, ctx)
				if indent != "" {
					if dec.More() {
						f.write("\n" + f.indentStr(len(stack)))
					} else {
						f.write("\n")
					}
				}
			case '}', ']':
				if len(stack) > 0 {
					stack = stack[:len(stack)-1]
				}
				if indent != "" {
					f.write("\n" + f.indentStr(len(stack)))
				}
				f.write(f.yellow(string(t)))
				afterValue()
			}
		case string:
			if len(stack) > 0 && stack[len(stack)-1].object == 1 && stack[len(stack)-1].expectKey {
				f.write(f.blue(fmt.Sprintf("%q", t)))
				f.write(": ")
				stack[len(stack)-1].expectKey = false
			} else {
				f.write(f.green(fmt.Sprintf("%q", t)))
				afterValue()
			}
		case json.Number:
			f.write(f.green(t.String()))
			afterValue()
		case bool:
			if t {
				f.write(f.green("true"))
			} else {
				f.write(f.green("false"))
			}
			afterValue()
		case nil:
			f.write(f.green("null"))
			afterValue()
		case float64:
			// Should not happen with UseNumber, keep Go-ish rendering just in case.
			f.write(f.green(fmt.Sprintf("%v", t)))
			afterValue()
		default:
			f.write(f.green(fmt.Sprintf("%v", t)))
			afterValue()
		}
	}
}
