package main

import (
	"encoding/xml"
	"errors"
	"fmt"
	"io"
	"strings"

	"golang.org/x/net/html/charset"
)

type xmlKind int

const (
	kindDocument xmlKind = iota
	kindDeclaration
	kindElement
	kindText
	kindComment
	kindDirective
	kindProcInst
	kindAttr
)

type xmlAttr struct {
	Space        string // raw token space: prefix ("xmlns", "xml", other prefix, or "")
	Local        string
	Prefix       string
	NamespaceURI string
	Value        string
}

type xmlNode struct {
	Kind         xmlKind
	Data         string
	Prefix       string
	NamespaceURI string
	Attr         []xmlAttr
	Parent       *xmlNode
	Children     []*xmlNode
	Order        int
	// Attribute virtual nodes.
	Owner     *xmlNode
	AttrIndex int
	AttrValue string
	// Document-only hidden text consumed before the document is activated.
	hiddenPreText    string
	hasHiddenPreText bool
}

func (n *xmlNode) addChild(c *xmlNode) {
	c.Parent = n
	n.Children = append(n.Children, c)
}

func jsonCharsetReader(charsetName string, input io.Reader) (io.Reader, error) {
	return charset.NewReaderLabel(charsetName, input)
}

type nsDecl struct {
	prefix string
	uri    string
}

func parseXMLDOM(r io.Reader, charsetReader func(string, io.Reader) (io.Reader, error), strictNS bool) (*xmlNode, error) {
	dec := xml.NewDecoder(r)
	dec.Strict = false
	dec.CharsetReader = charsetReader

	doc := &xmlNode{Kind: kindDocument}
	decl := &xmlNode{Kind: kindDeclaration, Data: "xml", Attr: []xmlAttr{{Local: "version", Value: "1.0"}}}
	doc.addChild(decl)
	order := 2
	nextOrder := func() int { order++; return order }

	var stack []*xmlNode
	var nsStack [][]nsDecl // parallel to stack

	activated := false
	rootSeen := false
	piBeforeRoot := false
	firstToken := true

	lookupPrefix := func(prefix string, own []nsDecl) (string, bool) {
		// own first, then enclosing frames innermost-first.
		for _, d := range own {
			if d.prefix == prefix {
				return d.uri, true
			}
		}
		for i := len(nsStack) - 1; i >= 0; i-- {
			for _, d := range nsStack[i] {
				if d.prefix == prefix {
					return d.uri, true
				}
			}
		}
		return "", false
	}

	popToEnd := func(end xml.EndElement) error {
		for {
			if len(stack) == 0 {
				line, _ := dec.InputPos()
				return &xml.SyntaxError{Msg: "unexpected end element </" + end.Name.Local + ">", Line: line}
			}
			top := stack[len(stack)-1]
			// Raw end name: Space is raw prefix.
			if top.Data != end.Name.Local {
				// Synthetically close intervening element.
				stack = stack[:len(stack)-1]
				nsStack = nsStack[:len(nsStack)-1]
				continue
			}
			// Locals match; spaces (raw prefixes) must match the start's raw prefix.
			startPrefix := top.Prefix
			// For an element whose prefix was dropped because undeclared, Prefix is ""
			// but the raw prefix is in NamespaceURI-ish fallback; we stored raw prefix
			// in a synthetic way below via origPrefix field encoded in AttrValue for
			// elements (see creation). Use it if present.
			if top.AttrValue != "" {
				startPrefix = top.AttrValue
			}
			if startPrefix != end.Name.Space {
				line, _ := dec.InputPos()
				return &xml.SyntaxError{Msg: fmt.Sprintf("element <%s> in space %s closed by </%s> in space %s", end.Name.Local, startPrefix, end.Name.Local, end.Name.Space), Line: line}
			}
			stack = stack[:len(stack)-1]
			nsStack = nsStack[:len(nsStack)-1]
			return nil
		}
	}

	for {
		tok, err := dec.RawToken()
		isFirst := firstToken
		firstToken = false
		if err == io.EOF {
			if len(stack) != 0 {
				// Token() would turn EOF with open elements into unexpected EOF.
				// But a start element whose text ran to EOF: RawToken returns
				// the CharData then EOF on next call; mirror Token().
				line, _ := dec.InputPos()
				return nil, &xml.SyntaxError{Msg: "unexpected EOF", Line: line}
			}
			break
		}
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			// Collect own namespace declarations (raw attrs).
			var own []nsDecl
			for _, a := range t.Attr {
				if a.Name.Space == "xmlns" {
					own = append(own, nsDecl{prefix: a.Name.Local, uri: a.Value})
				} else if a.Name.Space == "" && a.Name.Local == "xmlns" {
					own = append(own, nsDecl{prefix: "", uri: a.Value})
				}
			}
			rawPrefix := t.Name.Space
			if strictNS && rawPrefix != "" && rawPrefix != "xml" && rawPrefix != "xmlns" {
				if _, ok := lookupPrefix(rawPrefix, own); !ok {
					return nil, fmt.Errorf("xmlquery: invalid XML document, namespace %s is missing", rawPrefix)
				}
			}
			node := &xmlNode{Kind: kindElement, Data: t.Name.Local, Order: nextOrder(), AttrValue: rawPrefix}
			// Element namespace URI / prefix.
			switch {
			case rawPrefix == "xml":
				node.Prefix = "xml"
				node.NamespaceURI = "http://www.w3.org/XML/1998/namespace"
			case rawPrefix == "":
				if uri, ok := lookupPrefix("", own); ok {
					node.NamespaceURI = uri
				}
			default:
				if uri, ok := lookupPrefix(rawPrefix, own); ok {
					node.Prefix = rawPrefix
					node.NamespaceURI = uri
				} else {
					node.NamespaceURI = rawPrefix
				}
			}
			for _, a := range t.Attr {
				at := xmlAttr{Space: a.Name.Space, Local: a.Name.Local, Value: a.Value}
				switch {
				case a.Name.Space == "xmlns":
					at.Prefix = "xmlns"
					at.NamespaceURI = "xmlns"
				case a.Name.Space == "" && a.Name.Local == "xmlns":
					// prefix and uri stay empty
				case a.Name.Space == "xml":
					at.Prefix = "xml"
					at.NamespaceURI = "http://www.w3.org/XML/1998/namespace"
				case a.Name.Space != "":
					at.Prefix = a.Name.Space
					if uri, ok := lookupPrefix(a.Name.Space, own); ok {
						at.NamespaceURI = uri
					} else {
						at.NamespaceURI = a.Name.Space
					}
				}
				node.Attr = append(node.Attr, at)
			}
			if len(stack) == 0 {
				if !rootSeen {
					rootSeen = true
					activated = true
				}
				doc.addChild(node)
			} else {
				stack[len(stack)-1].addChild(node)
			}
			stack = append(stack, node)
			nsStack = append(nsStack, own)
		case xml.EndElement:
			if err := popToEnd(t); err != nil {
				return nil, err
			}
		case xml.CharData:
			s := string(t)
			if strings.TrimSpace(s) == "" {
				continue
			}
			if len(stack) == 0 && !activated {
				if isFirst {
					doc.hiddenPreText = s
					doc.hasHiddenPreText = true
				}
				continue
			}
			node := &xmlNode{Kind: kindText, Data: s, Order: nextOrder()}
			if len(stack) == 0 {
				doc.addChild(node)
			} else {
				stack[len(stack)-1].addChild(node)
			}
		case xml.Comment:
			if len(stack) == 0 && !activated {
				continue
			}
			node := &xmlNode{Kind: kindComment, Data: string(t), Order: nextOrder()}
			if len(stack) == 0 {
				doc.addChild(node)
			} else {
				stack[len(stack)-1].addChild(node)
			}
		case xml.Directive:
			if len(stack) == 0 && !activated {
				continue
			}
			node := &xmlNode{Kind: kindDirective, Data: string(t), Order: nextOrder()}
			if len(stack) == 0 {
				doc.addChild(node)
			} else {
				stack[len(stack)-1].addChild(node)
			}
		case xml.ProcInst:
			attrs := parseProcInstAttrs(string(t.Inst))
			if len(stack) == 0 && !rootSeen {
				activated = true
				if !piBeforeRoot {
					piBeforeRoot = true
					decl.Data = t.Target
					decl.Attr = attrs
					continue
				}
				node := &xmlNode{Kind: kindProcInst, Data: t.Target, Attr: attrs, Order: nextOrder()}
				doc.addChild(node)
			} else {
				node := &xmlNode{Kind: kindProcInst, Data: t.Target, Attr: attrs, Order: nextOrder()}
				if len(stack) == 0 {
					doc.addChild(node)
				} else {
					stack[len(stack)-1].addChild(node)
				}
			}
		}
	}
	if !rootSeen {
		return nil, errors.New("xmlquery: invalid XML document")
	}
	return doc, nil
}

func parseProcInstAttrs(inst string) []xmlAttr {
	var out []xmlAttr
	for _, part := range strings.Fields(inst) {
		kv := strings.SplitN(part, "=", 2)
		if len(kv) != 2 {
			continue
		}
		v := kv[1]
		if len(v) >= 2 {
			if (v[0] == '"' && v[len(v)-1] == '"') || (v[0] == '\'' && v[len(v)-1] == '\'') {
				v = v[1 : len(v)-1]
			}
		}
		out = append(out, xmlAttr{Local: kv[0], Value: v})
	}
	return out
}

// stringValue is the XPath string-value (raw, untrimmed), with
// antchfx-compatible quirks for document/declaration/directive nodes.
func (n *xmlNode) stringValue() string {
	switch n.Kind {
	case kindDocument, kindDeclaration, kindDirective, kindProcInst:
		return ""
	case kindText, kindComment:
		return n.Data
	case kindAttr:
		return n.AttrValue
	case kindElement:
		var b strings.Builder
		var walk func(*xmlNode)
		walk = func(x *xmlNode) {
			for _, c := range x.Children {
				if c.Kind == kindText {
					b.WriteString(c.Data)
				} else {
					walk(c)
				}
			}
		}
		walk(n)
		return b.String()
	}
	return ""
}

func (n *xmlNode) localName() string {
	// antchfx navigator returns Data as local name for all node types.
	if n.Kind == kindDocument {
		return ""
	}
	return n.Data
}

func (n *xmlNode) qname() string {
	switch n.Kind {
	case kindElement:
		if n.Prefix != "" {
			return n.Prefix + ":" + n.Data
		}
		return n.Data
	case kindAttr:
		if n.Prefix != "" {
			return n.Prefix + ":" + n.Data
		}
		return n.Data
	case kindDocument:
		return ""
	default:
		return n.Data
	}
}

// outputXML serializes a node like xmlquery's OutputXML(node, true-ish):
// the node itself plus descendants.
func outputXML(n *xmlNode) string {
	var b strings.Builder
	writeNodeXML(&b, n)
	return b.String()
}

func writeNodeXML(b *strings.Builder, n *xmlNode) {
	switch n.Kind {
	case kindDocument:
		for _, c := range n.Children {
			writeNodeXML(b, c)
		}
	case kindDeclaration, kindProcInst:
		b.WriteString("<?")
		b.WriteString(n.Data)
		for _, a := range n.Attr {
			b.WriteString(" " + a.Local + "=\"" + xmlEscape(a.Value) + "\"")
		}
		b.WriteString("?>")
	case kindElement:
		b.WriteString("<")
		b.WriteString(n.qname())
		for _, a := range n.Attr {
			name := a.Local
			if a.Prefix != "" {
				name = a.Prefix + ":" + a.Local
			}
			b.WriteString(" " + name + "=\"" + xmlEscape(a.Value) + "\"")
		}
		if len(n.Children) == 0 {
			b.WriteString("/>")
			return
		}
		b.WriteString(">")
		for _, c := range n.Children {
			writeNodeXML(b, c)
		}
		b.WriteString("</" + n.qname() + ">")
	case kindText:
		b.WriteString(xmlEscapeText(n.Data))
	case kindComment:
		b.WriteString("<!--" + n.Data + "-->")
	case kindDirective:
		b.WriteString("<!" + n.Data + ">")
	case kindAttr:
		b.WriteString("<" + n.qname() + ">" + xmlEscapeText(n.AttrValue) + "</" + n.qname() + ">")
	}
}

// xmlEscapeText escapes text the way Go's xml.EscapeText does for
// characters that matter in content (the result is re-parsed by the
// formatter, so exact entity choices mostly wash out).
func xmlEscapeText(s string) string {
	r := strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;",
		">", "&gt;",
		`"`, "&#34;",
		"'", "&#39;",
		"\t", "&#x9;",
		"\n", "&#xA;",
		"\r", "&#xD;",
	)
	return r.Replace(s)
}
