// ---------- errors ----------
var errXPathParse = errors.New("xpath parse error")
var errNamespaceAxis = errors.New("namespace axis")

type xpFuncError struct{ msg string }

func (e *xpFuncError) Error() string { return e.msg }

// ---------- lexer ----------
type xpTokKind int

const (
	xpEOF xpTokKind = iota
	xpName
	xpNumber
	xpLiteral
	xpOp
)

type xpTok struct {
	kind xpTokKind
	text string
}

type xpLexer struct {
	s string
	i int
}

func isNCNameStart(r rune) bool { return r == '_' || unicode.IsLetter(r) }
func isNCNameChar(r rune) bool {
	return r == '_' || r == '-' || r == '.' || unicode.IsLetter(r) || unicode.IsDigit(r)
}

func (l *xpLexer) tokenize() ([]xpTok, error) {
	var toks []xpTok
	for l.i < len(l.s) {
		c := l.s[l.i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			l.i++
			continue
		}
		rest := l.s[l.i:]
		switch {
		case strings.HasPrefix(rest, "//"):
			toks = append(toks, xpTok{xpOp, "//"}); l.i += 2
		case strings.HasPrefix(rest, "::"):
			toks = append(toks, xpTok{xpOp, "::"}); l.i += 2
		case strings.HasPrefix(rest, ".."):
			toks = append(toks, xpTok{xpOp, ".."}); l.i += 2
		case strings.HasPrefix(rest, "!="):
			toks = append(toks, xpTok{xpOp, "!="}); l.i += 2
		case strings.HasPrefix(rest, "<="):
			toks = append(toks, xpTok{xpOp, "<="}); l.i += 2
		case strings.HasPrefix(rest, ">="):
			toks = append(toks, xpTok{xpOp, ">="}); l.i += 2
		case c == '\'' || c == '"':
			j := strings.IndexByte(l.s[l.i+1:], c)
			if j < 0 {
				return nil, errXPathParse
			}
			toks = append(toks, xpTok{xpLiteral, l.s[l.i+1 : l.i+1+j]})
			l.i += j + 2
		case c >= '0' && c <= '9' || (c == '.' && l.i+1 < len(l.s) && l.s[l.i+1] >= '0' && l.s[l.i+1] <= '9'):
			start := l.i
			seenDot := false
			for l.i < len(l.s) {
				ch := l.s[l.i]
				if ch >= '0' && ch <= '9' {
					l.i++
				} else if ch == '.' && !seenDot {
					seenDot = true; l.i++
				} else { break }
			}
			toks = append(toks, xpTok{xpNumber, l.s[start:l.i]})
		default:
			r, size := rune(c), 1
			if c >= 0x80 {
				r, size = []rune(rest)[0], len(string([]rune(rest)[0]))
			}
			if isNCNameStart(r) {
				start := l.i
				l.i += size
				for l.i < len(l.s) {
					r2, sz := rune(l.s[l.i]), 1
					if l.s[l.i] >= 0x80 {
						rr := []rune(l.s[l.i:])[0]; r2 = rr; sz = len(string(rr))
					}
					if isNCNameChar(r2) {
						// Stop ".." from being eaten as trailing name dots isn't
						// critical; keep greedy except don't consume '.' if it
						// starts ".." following a completed name? Standard
						// lexers are greedy on NCName incl dots.
						l.i += sz
					} else { break }
				}
				name := l.s[start:l.i]
				// QName prefix:local or prefix:*
				if l.i < len(l.s) && l.s[l.i] == ':' && !(l.i+1 < len(l.s) && l.s[l.i+1] == ':') {
					if l.i+1 < len(l.s) && l.s[l.i+1] == '*' {
						name += ":*"; l.i += 2
					} else if l.i+1 < len(l.s) {
						// read local part
						j := l.i + 1
						r3, _ := rune(l.s[j]), 1
						if l.s[j] >= 0x80 { r3 = []rune(l.s[j:])[0] }
						if isNCNameStart(r3) {
							k := j
							for k < len(l.s) {
								r4, sz4 := rune(l.s[k]), 1
								if l.s[k] >= 0x80 { rr := []rune(l.s[k:])[0]; r4 = rr; sz4 = len(string(rr)) }
								if isNCNameChar(r4) { k += sz4 } else { break }
							}
							name = l.s[start:k]; l.i = k
						}
					}
				}
				toks = append(toks, xpTok{xpName, name})
			} else if strings.IndexByte("/|@[],(),.=<>+-*$", c) >= 0 {
				toks = append(toks, xpTok{xpOp, string(c)}); l.i++
			} else {
				return nil, errXPathParse
			}
		}
	}
	toks = append(toks, xpTok{xpEOF, ""})
	return toks, nil
}

// ---------- AST ----------
type xpExpr interface{ isExpr() }

type xpLiteral struct{ val string }
type xpNumLit struct{ val float64 }
type xpVar struct{ name string }
type xpFuncCall struct {
	name string
	args []xpExpr
}
type xpBinary struct {
	op          string
	left, right xpExpr
}
type xpUnary struct{ expr xpExpr } // negation
type xpUnion struct{ parts []xpExpr }
type xpFilter struct {
	base       xpExpr
	preds      []xpExpr
}
type xpPath struct {
	absolute bool
	base     xpExpr // non-nil if this path continues a filter/primary
	steps    []*xpStep
}
type xpStep struct {
	descOrSelf bool // preceded by //
	axis       string
	testKind   string // "name", "node", "text", "comment", "pi", "pi-lit"
	testName   string // raw test text / pi literal
	preds      []xpExpr
}

func (*xpLiteral) isExpr()  {}
func (*xpNumLit) isExpr()   {}
func (*xpVar) isExpr()      {}
func (*xpFuncCall) isExpr() {}
func (*xpBinary) isExpr()   {}
func (*xpUnary) isExpr()    {}
func (*xpUnion) isExpr()    {}
func (*xpFilter) isExpr()   {}
func (*xpPath) isExpr()     {}

var xpAxes = map[string]bool{
	"ancestor": true, "ancestor-or-self": true, "attribute": true, "child": true,
	"descendant": true, "descendant-or-self": true, "following": true,
	"following-sibling": true, "namespace": true, "parent": true,
	"preceding": true, "preceding-sibling": true, "self": true,
}

var xpFunctions = map[string]bool{
	"last": true, "position": true, "count": true, "local-name": true,
	"namespace-uri": true, "name": true, "string": true, "concat": true,
	"starts-with": true, "contains": true, "substring-before": true,
	"substring-after": true, "substring": true, "string-length": true,
	"normalize-space": true, "translate": true, "boolean": true, "not": true,
	"true": true, "false": true, "lang": true, "number": true, "sum": true,
	"floor": true, "ceiling": true, "round": true,
}

type xpParser struct {
	toks []xpTok
	pos  int
}

func (p *xpParser) peek() xpTok  { return p.toks[p.pos] }
func (p *xpParser) peekAt(n int) xpTok {
	if p.pos+n >= len(p.toks) { return p.toks[len(p.toks)-1] }
	return p.toks[p.pos+n]
}
func (p *xpParser) next() xpTok { t := p.toks[p.pos]; if p.pos < len(p.toks)-1 { p.pos++ }; return t }
func (p *xpParser) isOp(s string) bool { t := p.peek(); return t.kind == xpOp && t.text == s }
func (p *xpParser) isName(s string) bool { t := p.peek(); return t.kind == xpName && t.text == s }
func (p *xpParser) expectOp(s string) error {
	if !p.isOp(s) { return errXPathParse }
	p.next(); return nil
}

func parseXPath(s string) (xpExpr, error) {
	lx := &xpLexer{s: s}
	toks, err := lx.tokenize()
	if err != nil { return nil, err }
	p := &xpParser{toks: toks}
	if p.peek().kind == xpEOF { return nil, errXPathParse }
	return p.parseExpr()
}

func (p *xpParser) parseExpr() (xpExpr, error) { return p.parseOr() }

func (p *xpParser) parseOr() (xpExpr, error) {
	left, err := p.parseAnd(); if err != nil { return nil, err }
	for p.isName("or") {
		p.next(); right, err := p.parseAnd(); if err != nil { return nil, err }
		left = &xpBinary{op: "or", left: left, right: right}
	}
	return left, nil
}
func (p *xpParser) parseAnd() (xpExpr, error) {
	left, err := p.parseEquality(); if err != nil { return nil, err }
	for p.isName("and") {
		p.next(); right, err := p.parseEquality(); if err != nil { return nil, err }
		left = &xpBinary{op: "and", left: left, right: right}
	}
	return left, nil
}
func (p *xpParser) parseEquality() (xpExpr, error) {
	left, err := p.parseRelational(); if err != nil { return nil, err }
	for p.isOp("=") || p.isOp("!=") {
		op := p.next().text; right, err := p.parseRelational(); if err != nil { return nil, err }
		left = &xpBinary{op: op, left: left, right: right}
	}
	return left, nil
}
func (p *xpParser) parseRelational() (xpExpr, error) {
	left, err := p.parseAdditive(); if err != nil { return nil, err }
	for p.isOp("<") || p.isOp("<=") || p.isOp(">") || p.isOp(">=") {
		op := p.next().text; right, err := p.parseAdditive(); if err != nil { return nil, err }
		left = &xpBinary{op: op, left: left, right: right}
	}
	return left, nil
}
func (p *xpParser) parseAdditive() (xpExpr, error) {
	left, err := p.parseMultiplicative(); if err != nil { return nil, err }
	for p.isOp("+") || p.isOp("-") {
		op := p.next().text; right, err := p.parseMultiplicative(); if err != nil { return nil, err }
		left = &xpBinary{op: op, left: left, right: right}
	}
	return left, nil
}
func (p *xpParser) parseMultiplicative() (xpExpr, error) {
	left, err := p.parseUnary(); if err != nil { return nil, err }
	for {
		if p.isOp("*") {
			p.next(); right, err := p.parseUnary(); if err != nil { return nil, err }
			left = &xpBinary{op: "*", left: left, right: right}
		} else if p.isName("div") || p.isName("mod") {
			op := p.next().text; right, err := p.parseUnary(); if err != nil { return nil, err }
			left = &xpBinary{op: op, left: left, right: right}
		} else { break }
	}
	return left, nil
}
func (p *xpParser) parseUnary() (xpExpr, error) {
	if p.isOp("-") {
		p.next(); e, err := p.parseUnary(); if err != nil { return nil, err }
		return &xpUnary{expr: e}, nil
	}
	return p.parseUnion()
}
func (p *xpParser) parseUnion() (xpExpr, error) {
	first, err := p.parsePathExpr(); if err != nil { return nil, err }
	if !p.isOp("|") { return first, nil }
	parts := []xpExpr{first}
	for p.isOp("|") {
		p.next(); e, err := p.parsePathExpr(); if err != nil { return nil, err }
		parts = append(parts, e)
	}
	return &xpUnion{parts: parts}, nil
}

func (p *xpParser) canStartStep() bool {
	t := p.peek()
	if t.kind == xpOp && (t.text == "*" || t.text == "@" || t.text == "." || t.text == "..") { return true }
	if t.kind == xpName {
		// function call that isn't a node type cannot start a step
		if p.peekAt(1).kind == xpOp && p.peekAt(1).text == "(" {
			switch t.text {
			case "node", "text", "comment", "processing-instruction":
				return true
			}
			return false
		}
		return true
	}
	return false
}

func (p *xpParser) parsePathExpr() (xpExpr, error) {
	if p.isOp("/") || p.isOp("//") {
		sep := p.next().text
		path := &xpPath{absolute: true}
		if p.canStartStep() {
			steps, err := p.parseSteps(sep == "//")
			if err != nil { return nil, err }
			path.steps = steps
		} else if sep == "//" {
			return nil, errXPathParse
		}
		return path, nil
	}
	if p.canStartStep() {
		steps, err := p.parseSteps(false)
		if err != nil { return nil, err }
		return &xpPath{steps: steps}, nil
	}
	// Filter / primary
	prim, err := p.parsePrimary(); if err != nil { return nil, err }
	var result xpExpr = prim
	if p.isOp("[") {
		preds, err := p.parsePredicates(); if err != nil { return nil, err }
		result = &xpFilter{base: prim, preds: preds}
	}
	if p.isOp("/") || p.isOp("//") {
		sep := p.next().text
		if !p.canStartStep() { return nil, errXPathParse }
		steps, err := p.parseSteps(sep == "//")
		if err != nil { return nil, err }
		return &xpPath{base: result, steps: steps}, nil
	}
	return result, nil
}

func (p *xpParser) parseSteps(firstDesc bool) ([]*xpStep, error) {
	var steps []*xpStep
	desc := firstDesc
	for {
		st, err := p.parseStep()
		if err != nil { return nil, err }
		st.descOrSelf = desc
		steps = append(steps, st)
		if p.isOp("/") || p.isOp("//") {
			sep := p.next().text
			if !p.canStartStep() { return nil, errXPathParse }
			desc = sep == "//"
			continue
		}
		break
	}
	return steps, nil
}

func (p *xpParser) parseStep() (*xpStep, error) {
	st := &xpStep{axis: "child", testKind: "name"}
	if p.isOp(".") {
		p.next(); st.axis = "self"; st.testKind = "node"
	} else if p.isOp("..") {
		p.next(); st.axis = "parent"; st.testKind = "node"
	} else {
		if p.isOp("@") {
			p.next(); st.axis = "attribute"
		} else if p.peek().kind == xpName && p.peekAt(1).kind == xpOp && p.peekAt(1).text == "::" {
			axis := p.next().text; p.next()
			if !xpAxes[axis] { return nil, errXPathParse }
			st.axis = axis
		}
		// node test
		t := p.peek()
		if t.kind == xpOp && t.text == "*" {
			p.next(); st.testKind = "name"; st.testName = "*"
		} else if t.kind == xpName {
			name := t.text
			if (name == "node" || name == "text" || name == "comment" || name == "processing-instruction") && p.peekAt(1).kind == xpOp && p.peekAt(1).text == "(" {
				p.next(); p.next()
				if name == "processing-instruction" {
					if p.peek().kind == xpLiteral {
						st.testKind = "pi-lit"; st.testName = p.next().text
					} else {
						st.testKind = "pi"
					}
				} else {
					st.testKind = name
				}
				if err := p.expectOp(")"); err != nil { return nil, err }
			} else {
				p.next(); st.testKind = "name"; st.testName = name
			}
		} else {
			return nil, errXPathParse
		}
	}
	if p.isOp("[") {
		preds, err := p.parsePredicates(); if err != nil { return nil, err }
		st.preds = preds
	}
	return st, nil
}

func (p *xpParser) parsePredicates() ([]xpExpr, error) {
	var preds []xpExpr
	for p.isOp("[") {
		p.next()
		e, err := p.parseExpr(); if err != nil { return nil, err }
		if err := p.expectOp("]"); err != nil { return nil, err }
		preds = append(preds, e)
	}
	return preds, nil
}

func (p *xpParser) parsePrimary() (xpExpr, error) {
	t := p.peek()
	switch {
	case t.kind == xpLiteral:
		p.next(); return &xpLiteral{val: t.text}, nil
	case t.kind == xpNumber:
		p.next(); v, _ := strconv.ParseFloat(t.text, 64); return &xpNumLit{val: v}, nil
	case p.isOp("("):
		p.next(); e, err := p.parseExpr(); if err != nil { return nil, err }
		if err := p.expectOp(")"); err != nil { return nil, err }
		return e, nil
	case p.isOp("$"):
		p.next(); name := p.next()
		if name.kind != xpName { return nil, errXPathParse }
		return &xpVar{name: name.text}, nil
	case t.kind == xpName:
		// function call
		name := p.next().text
		if err := p.expectOp("("); err != nil { return nil, err }
		var args []xpExpr
		if !p.isOp(")") {
			for {
				a, err := p.parseExpr(); if err != nil { return nil, err }
				args = append(args, a)
				if p.isOp(",") { p.next(); continue }
				break
			}
		}
		if err := p.expectOp(")"); err != nil { return nil, err }
		return &xpFuncCall{name: name, args: args}, nil
	}
	return nil, errXPathParse
}

// validate functions (unknown names) anywhere in the AST.
func validateXPathFunctions(e xpExpr) error {
	switch x := e.(type) {
	case *xpFuncCall:
		if !xpFunctions[x.name] {
			return &xpFuncError{msg: fmt.Sprintf("not yet support this function %s()", x.name)}
		}
		for _, a := range x.args { if err := validateXPathFunctions(a); err != nil { return err } }
	case *xpBinary:
		if err := validateXPathFunctions(x.left); err != nil { return err }
		return validateXPathFunctions(x.right)
	case *xpUnary:
		return validateXPathFunctions(x.expr)
	case *xpUnion:
		for _, a := range x.parts { if err := validateXPathFunctions(a); err != nil { return err } }
	case *xpFilter:
		if err := validateXPathFunctions(x.base); err != nil { return err }
		for _, a := range x.preds { if err := validateXPathFunctions(a); err != nil { return err } }
	case *xpPath:
		if x.base != nil { if err := validateXPathFunctions(x.base); err != nil { return err } }
		for _, st := range x.steps {
			for _, a := range st.preds { if err := validateXPathFunctions(a); err != nil { return err } }
		}
	}
	return nil
}

func xpContainsNamespaceAxis(e xpExpr) bool {
	switch x := e.(type) {
	case *xpPath:
		if x.base != nil && xpContainsNamespaceAxis(x.base) { return true }
		for _, st := range x.steps {
			if st.axis == "namespace" { return true }
			for _, a := range st.preds { if xpContainsNamespaceAxis(a) { return true } }
		}
	case *xpFilter:
		if xpContainsNamespaceAxis(x.base) { return true }
		for _, a := range x.preds { if xpContainsNamespaceAxis(a) { return true } }
	case *xpBinary:
		return xpContainsNamespaceAxis(x.left) || xpContainsNamespaceAxis(x.right)
	case *xpUnary:
		return xpContainsNamespaceAxis(x.expr)
	case *xpUnion:
		for _, a := range x.parts { if xpContainsNamespaceAxis(a) { return true } }
	case *xpFuncCall:
		for _, a := range x.args { if xpContainsNamespaceAxis(a) { return true } }
	}
	return false
}

func xpIsNodeSetShaped(e xpExpr) bool {
	switch x := e.(type) {
	case *xpPath:
		return true
	case *xpFilter:
		return xpIsNodeSetShaped(x.base)
	case *xpUnion:
		return true
	case *xpVar:
		return false
	}
	return false
}

// ---------- values ----------
type xpValKind int

const (
	xvNodes xpValKind = iota
	xvString
	xvNumber
	xvBool
)

type xpVal struct {
	kind  xpValKind
	nodes []*xmlNode
	s     string
	n     float64
	b     bool
	isInt bool // round() result: triggers unknown-type in -x text mode
}

func nodesVal(ns []*xmlNode) xpVal {
	if ns == nil { ns = []*xmlNode{} }
	return xpVal{kind: xvNodes, nodes: ns}
}

type xpCtx struct {
	node *xmlNode
	pos  int
	size int
}

type xpEval struct {
	doc       *xmlNode
	all       []*xmlNode // preorder incl document
	startIdx  map[*xmlNode]int
	endIdx    map[*xmlNode]int
	attrCache map[*xmlNode][]*xmlNode
}

func newXpEval(doc *xmlNode) *xpEval {
	ev := &xpEval{doc: doc, startIdx: map[*xmlNode]int{}, endIdx: map[*xmlNode]int{}, attrCache: map[*xmlNode][]*xmlNode{}}
	var walk func(n *xmlNode)
	idx := 0
	walk = func(n *xmlNode) {
		ev.startIdx[n] = idx
		ev.all = append(ev.all, n)
		idx++
		for _, c := range n.Children { walk(c) }
		ev.endIdx[n] = idx - 1
	}
	walk(doc)
	return ev
}

func (ev *xpEval) attrNodes(n *xmlNode) []*xmlNode {
	if n.Kind != kindElement { return nil }
	if cached, ok := ev.attrCache[n]; ok { return cached }
	var out []*xmlNode
	for i, a := range n.Attr {
		out = append(out, &xmlNode{Kind: kindAttr, Data: a.Local, Prefix: a.Prefix, NamespaceURI: a.NamespaceURI, AttrValue: a.Value, Owner: n, Parent: n, AttrIndex: i, Order: n.Order})
	}
	ev.attrCache[n] = out
	return out
}

func xpToString(v xpVal) string {
	switch v.kind {
	case xvNodes:
		if len(v.nodes) == 0 { return "" }
		return v.nodes[0].stringValue()
	case xvString:
		return v.s
	case xvBool:
		if v.b { return "true" }
		return "false"
	case xvNumber:
		return xpNumToString(v.n)
	}
	return ""
}

func xpNumToString(n float64) string {
	if math.IsNaN(n) { return "NaN" }
	if math.IsInf(n, 1) { return "+Inf" }
	if math.IsInf(n, -1) { return "-Inf" }
	// antchfx uses strconv.FormatFloat(..., 'f', -1, 64) style.
	if n == 0 && math.Signbit(n) { return "-0" }
	return strconv.FormatFloat(n, 'f', -1, 64)
}

func xpToNumber(v xpVal) float64 {
	switch v.kind {
	case xvNumber:
		return v.n
	case xvBool:
		if v.b { return 1 }
		return 0
	default:
		s := strings.TrimSpace(xpToString(v))
		f, err := strconv.ParseFloat(s, 64)
		if err != nil { return math.NaN() }
		return f
	}
}

func xpToBool(v xpVal) bool {
	switch v.kind {
	case xvNodes:
		return len(v.nodes) > 0
	case xvString:
		return len(v.s) > 0
	case xvNumber:
		return v.n != 0 && !math.IsNaN(v.n)
	case xvBool:
		return v.b
	}
	return false
}

// ---------- axis ----------
func (ev *xpEval) parentOf(n *xmlNode) *xmlNode {
	if n.Kind == kindAttr { return n.Owner }
	return n.Parent
}

func (ev *xpEval) axisNodes(axis string, n *xmlNode) []*xmlNode {
	switch axis {
	case "self":
		return []*xmlNode{n}
	case "child":
		if n.Kind == kindAttr { return nil }
		return append([]*xmlNode{}, n.Children...)
	case "parent":
		if p := ev.parentOf(n); p != nil { return []*xmlNode{p} }
		return nil
	case "ancestor":
		var out []*xmlNode
		for p := ev.parentOf(n); p != nil; p = ev.parentOf(p) { out = append(out, p) }
		return out
	case "ancestor-or-self":
		out := []*xmlNode{n}
		for p := ev.parentOf(n); p != nil; p = ev.parentOf(p) { out = append(out, p) }
		return out
	case "descendant":
		if n.Kind == kindAttr { return nil }
		var out []*xmlNode
		var walk func(x *xmlNode)
		walk = func(x *xmlNode) { for _, c := range x.Children { out = append(out, c); walk(c) } }
		walk(n)
		return out
	case "descendant-or-self":
		out := []*xmlNode{n}
		out = append(out, ev.axisNodes("descendant", n)...)
		return out
	case "attribute":
		return ev.attrNodes(n)
	case "following-sibling", "preceding-sibling":
		if n.Kind == kindAttr || n.Parent == nil { return nil }
		sibs := n.Parent.Children
		idx := -1
		for i, s := range sibs { if s == n { idx = i; break } }
		if idx < 0 { return nil }
		if axis == "following-sibling" { return append([]*xmlNode{}, sibs[idx+1:]...) }
		out := []*xmlNode{}
		for i := idx - 1; i >= 0; i-- { out = append(out, sibs[i]) }
		return out
	case "following":
		// Nodes after n's subtree (for attrs, after the owner element's
		// start but that edge case just uses owner's subtree end... in
		// antchfx attributes' following starts after the element).
		base := n
		if n.Kind == kindAttr { base = n.Owner }
		end := ev.endIdx[base]
		var out []*xmlNode
		for _, x := range ev.all {
			if ev.startIdx[x] > end { out = append(out, x) }
		}
		return out
	case "preceding":
		base := n
		if n.Kind == kindAttr { base = n.Owner }
		start := ev.startIdx[base]
		anc := map[*xmlNode]bool{}
		for p := ev.parentOf(base); p != nil; p = ev.parentOf(p) { anc[p] = true }
		var out []*xmlNode
		for i := len(ev.all) - 1; i >= 0; i-- {
			x := ev.all[i]
			if ev.startIdx[x] < start && !anc[x] { out = append(out, x) }
		}
		return out
	case "namespace":
		panic(errNamespaceAxis)
	}
	return nil
}

func xpNameTestMatch(node *xmlNode, test string) bool {
	if test == "*" { return true }
	if strings.HasSuffix(test, ":*") {
		return node.Prefix == strings.TrimSuffix(test, ":*")
	}
	if i := strings.Index(test, ":"); i >= 0 {
		return node.Prefix == test[:i] && node.Data == test[i+1:]
	}
	return node.Prefix == "" && node.Data == test
}

func xpNodeTestMatch(ev *xpEval, st *xpStep, node *xmlNode) bool {
	isPrincipal := false
	if st.axis == "attribute" {
		isPrincipal = node.Kind == kindAttr
	} else {
		isPrincipal = node.Kind == kindElement || node.Kind == kindProcInst
	}
	switch st.testKind {
	case "node":
		return true
	case "text":
		return node.Kind == kindText
	case "comment":
		return node.Kind == kindComment
	case "pi":
		// antchfx bug: processing-instruction() behaves like *.
		return isPrincipal
	case "pi-lit":
		return (node.Kind == kindProcInst || node.Kind == kindDeclaration) && node.Data == st.testName
	case "name":
		if !isPrincipal { return false }
		return xpNameTestMatch(node, st.testName)
	}
	return false
}

func (ev *xpEval) applyPredicates(cands []*xmlNode, preds []xpExpr, docCtx *xmlNode) ([]*xmlNode, error) {
	cur := cands
	for _, pred := range preds {
		var next []*xmlNode
		for i, c := range cur {
			ctx := xpCtx{node: c, pos: i + 1, size: len(cur)}
			v, err := ev.eval(pred, ctx)
			if err != nil { return nil, err }
			if v.kind == xvNumber {
				if float64(i+1) == v.n { next = append(next, c) }
			} else if xpToBool(v) {
				next = append(next, c)
			}
		}
		cur = next
	}
	return cur, nil
}

func (ev *xpEval) applySteps(initial []*xmlNode, steps []*xpStep) ([]*xmlNode, error) {
	current := initial
	for _, st := range steps {
		var contextNodes []*xmlNode
		if st.descOrSelf {
			for _, c := range current {
				contextNodes = append(contextNodes, ev.axisNodes("descendant-or-self", c)...)
			}
		} else {
			contextNodes = current
		}
		var next []*xmlNode
		for _, c := range contextNodes {
			cands := ev.axisNodes(st.axis, c)
			var filtered []*xmlNode
			for _, cand := range cands {
				if xpNodeTestMatch(ev, st, cand) { filtered = append(filtered, cand) }
			}
			kept, err := ev.applyPredicates(filtered, st.preds, c)
			if err != nil { return nil, err }
			next = append(next, kept...)
		}
		current = next
		if current == nil { current = []*xmlNode{} }
	}
	return current, nil
}

// ---------- evaluation ----------
func (ev *xpEval) eval(e xpExpr, ctx xpCtx) (xpVal, error) {
	switch x := e.(type) {
	case *xpLiteral:
		return xpVal{kind: xvString, s: x.val}, nil
	case *xpNumLit:
		return xpVal{kind: xvNumber, n: x.val}, nil
	case *xpVar:
		return xpVal{}, &xpFuncError{msg: fmt.Sprintf("undeclared variable in XPath expression: $%s", x.name)}
	case *xpUnary:
		v, err := ev.eval(x.expr, ctx); if err != nil { return xpVal{}, err }
		return xpVal{kind: xvNumber, n: -xpToNumber(v)}, nil
	case *xpBinary:
		return ev.evalBinary(x, ctx)
	case *xpUnion:
		var all []*xmlNode
		seen := map[*xmlNode]bool{}
		for _, part := range x.parts {
			v, err := ev.eval(part, ctx); if err != nil { return xpVal{}, err }
			if v.kind != xvNodes { return xpVal{}, &xpFuncError{msg: "union of non-node-set"} }
			for _, n := range v.nodes {
				if !seen[n] { seen[n] = true; all = append(all, n) }
			}
		}
		return nodesVal(all), nil
	case *xpFilter:
		v, err := ev.eval(x.base, ctx); if err != nil { return xpVal{}, err }
		if v.kind != xvNodes { return xpVal{}, &xpFuncError{msg: "filter of non-node-set"} }
		kept, err := ev.applyPredicates(v.nodes, x.preds, ctx.node)
		if err != nil { return xpVal{}, err }
		return nodesVal(kept), nil
	case *xpPath:
		var initial []*xmlNode
		if x.absolute {
			initial = []*xmlNode{ev.doc}
		} else if x.base != nil {
			v, err := ev.eval(x.base, ctx); if err != nil { return xpVal{}, err }
			if v.kind != xvNodes { return xpVal{}, &xpFuncError{msg: "path of non-node-set"} }
			initial = v.nodes
		} else {
			initial = []*xmlNode{ctx.node}
		}
		nodes, err := ev.applySteps(initial, x.steps)
		if err != nil { return xpVal{}, err }
		return nodesVal(nodes), nil
	case *xpFuncCall:
		return ev.evalFunc(x, ctx)
	}
	return xpVal{}, &xpFuncError{msg: "unsupported expression"}
}

func (ev *xpEval) evalBinary(x *xpBinary, ctx xpCtx) (xpVal, error) {
	// Short-circuit-ish for and/or not needed for correctness of result.
	l, err := ev.eval(x.left, ctx); if err != nil { return xpVal{}, err }
	r, err := ev.eval(x.right, ctx); if err != nil { return xpVal{}, err }
	switch x.op {
	case "or":
		return xpVal{kind: xvBool, b: xpToBool(l) || xpToBool(r)}, nil
	case "and":
		return xpVal{kind: xvBool, b: xpToBool(l) && xpToBool(r)}, nil
	case "+", "-", "*", "div", "mod":
		a, b := xpToNumber(l), xpToNumber(r)
		var res float64
		switch x.op {
		case "+": res = a + b
		case "-": res = a - b
		case "*": res = a * b
		case "div": res = a / b
		case "mod": res = math.Mod(a, b)
		}
		return xpVal{kind: xvNumber, n: res}, nil
	case "=", "!=", "<", "<=", ">", ">=":
		res := xpCompare(x.op, l, r)
		return xpVal{kind: xvBool, b: res}, nil
	}
	return xpVal{}, &xpFuncError{msg: "unknown operator " + x.op}
}

func xpApplyCmp(op string, cmp int, equal bool) bool {
	switch op {
	case "=": return equal
	case "!=": return !equal
	case "<": return cmp < 0
	case "<=": return cmp < 0 || equal
	case ">": return cmp > 0
	case ">=": return cmp > 0 || equal
	}
	return false
}

func xpCompare(op string, l, r xpVal) bool {
	relational := op != "=" && op != "!="
	// If either is bool and not relational: compare booleans.
	if !relational && (l.kind == xvBool || r.kind == xvBool) {
		eq := xpToBool(l) == xpToBool(r)
		if op == "=" { return eq }
		return !eq
	}
	// node-set comparisons
	if l.kind == xvNodes || r.kind == xvNodes {
		if l.kind == xvNodes && r.kind == xvNodes {
			for _, a := range l.nodes {
				for _, b := range r.nodes {
					if relational {
						an, bn := xpToNumber(nodesVal([]*xmlNode{a})), xpToNumber(nodesVal([]*xmlNode{b}))
						if xpNumCmp(op, an, bn) { return true }
					} else {
						eq := a.stringValue() == b.stringValue()
						if op == "=" && eq { return true }
						if op == "!=" && !eq { return true }
					}
				}
			}
			return false
		}
		// one side nodeset
		var nodes []*xmlNode
		var other xpVal
		nodesFirst := l.kind == xvNodes
		if nodesFirst { nodes, other = l.nodes, r } else { nodes, other = r.nodes, l }
		for _, n := range nodes {
			var nodeVal, otherVal xpVal
			nodeVal = nodesVal([]*xmlNode{n}); otherVal = other
			var a, b xpVal
			if nodesFirst { a, b = nodeVal, otherVal } else { a, b = otherVal, nodeVal }
			if relational || other.kind == xvNumber {
				if xpNumCmp(op, xpToNumber(a), xpToNumber(b)) { return true }
			} else {
				eq := xpToString(a) == xpToString(b)
				if op == "=" && eq { return true }
				if op == "!=" && !eq { return true }
			}
		}
		return false
	}
	if relational || l.kind == xvNumber || r.kind == xvNumber {
		return xpNumCmp(op, xpToNumber(l), xpToNumber(r))
	}
	eq := xpToString(l) == xpToString(r)
	if op == "=" { return eq }
	return !eq
}

func xpNumCmp(op string, a, b float64) bool {
	if math.IsNaN(a) || math.IsNaN(b) {
		return op == "!="
	}
	switch op {
	case "=": return a == b
	case "!=": return a != b
	case "<": return a < b
	case "<=": return a <= b
	case ">": return a > b
	case ">=": return a >= b
	}
	return false
}

// ---------- functions ----------
func (ev *xpEval) evalFunc(x *xpFuncCall, ctx xpCtx) (xpVal, error) {
	name := x.name
	args := x.args
	evalArg := func(i int) (xpVal, error) { return ev.eval(args[i], ctx) }
	needNodes := func(i int) ([]*xmlNode, error) {
		v, err := evalArg(i)
		if err != nil { return nil, err }
		if v.kind != xvNodes { return nil, &xpFuncError{msg: fmt.Sprintf("xpath: %s argument must be a node-set", name)} }
		return v.nodes, nil
	}
	switch name {
	case "last":
		if len(args) != 0 { return xpVal{}, &xpFuncError{msg: "xpath: last function requires no arguments"} }
		return xpVal{kind: xvNumber, n: float64(ctx.size)}, nil
	case "position":
		if len(args) != 0 { return xpVal{}, &xpFuncError{msg: "xpath: position function requires no arguments"} }
		return xpVal{kind: xvNumber, n: float64(ctx.pos)}, nil
	case "count":
		if len(args) != 1 { return xpVal{}, &xpFuncError{msg: "xpath: count(node-sets) function must with have parameters node-sets"} }
		ns, err := needNodes(0); if err != nil { return xpVal{}, err }
		return xpVal{kind: xvNumber, n: float64(len(ns))}, nil
	case "string":
		if len(args) > 1 { return xpVal{}, &xpFuncError{msg: "xpath: string function must have at most one parameter"} }
		if len(args) == 0 { return xpVal{kind: xvString, s: ctx.node.stringValue()}, nil }
		v, err := evalArg(0); if err != nil { return xpVal{}, err }
		return xpVal{kind: xvString, s: xpToString(v)}, nil
	case "number":
		if len(args) > 1 { return xpVal{}, &xpFuncError{msg: "xpath: number function must have at most one parameter"} }
		if len(args) == 0 { return xpVal{kind: xvNumber, n: xpToNumber(nodesVal([]*xmlNode{ctx.node}))}, nil }
		v, err := evalArg(0); if err != nil { return xpVal{}, err }
		return xpVal{kind: xvNumber, n: xpToNumber(v)}, nil
	case "boolean":
		if len(args) != 1 { return xpVal{}, &xpFuncError{msg: "xpath: boolean function requires one argument"} }
		v, err := evalArg(0); if err != nil { return xpVal{}, err }
		return xpVal{kind: xvBool, b: xpToBool(v)}, nil
	case "not":
		if len(args) != 1 { return xpVal{}, &xpFuncError{msg: "xpath: not function requires one argument"} }
		v, err := evalArg(0); if err != nil { return xpVal{}, err }
		return xpVal{kind: xvBool, b: !xpToBool(v)}, nil
	case "true":
		return xpVal{kind: xvBool, b: true}, nil
	case "false":
		return xpVal{kind: xvBool, b: false}, nil
	case "concat":
		if len(args) < 2 { return xpVal{}, &xpFuncError{msg: "xpath: concat function must have at least two parameters"} }
		var sb strings.Builder
		for i := range args { v, err := evalArg(i); if err != nil { return xpVal{}, err }; sb.WriteString(xpToString(v)) }
		return xpVal{kind: xvString, s: sb.String()}, nil
	case "starts-with", "contains":
		if len(args) != 2 { return xpVal{}, &xpFuncError{msg: fmt.Sprintf("xpath: %s function requires two arguments", name)} }
		a, err := evalArg(0); if err != nil { return xpVal{}, err }
		b, err := evalArg(1); if err != nil { return xpVal{}, err }
		if name == "starts-with" { return xpVal{kind: xvBool, b: strings.HasPrefix(xpToString(a), xpToString(b))}, nil }
		return xpVal{kind: xvBool, b: strings.Contains(xpToString(a), xpToString(b))}, nil
	case "substring-before", "substring-after":
		if len(args) != 2 { return xpVal{}, &xpFuncError{msg: fmt.Sprintf("xpath: %s function requires two arguments", name)} }
		a, err := evalArg(0); if err != nil { return xpVal{}, err }
		b, err := evalArg(1); if err != nil { return xpVal{}, err }
		s, sub := xpToString(a), xpToString(b)
		if sub == "" { return xpVal{kind: xvString, s: ""}, nil }
		i := strings.Index(s, sub)
		if i < 0 { return xpVal{kind: xvString, s: ""}, nil }
		if name == "substring-before" { return xpVal{kind: xvString, s: s[:i]}, nil }
		return xpVal{kind: xvString, s: s[i+len(sub):]}, nil
	case "substring":
		if len(args) < 2 || len(args) > 3 { return xpVal{}, &xpFuncError{msg: "xpath: substring function requires two or three arguments"} }
		a, err := evalArg(0); if err != nil { return xpVal{}, err }
		sv, err := evalArg(1); if err != nil { return xpVal{}, err }
		s := []rune(xpToString(a))
		start := xpToNumber(sv)
		var out []rune
		if len(args) == 2 {
			for i, r := range s {
				if float64(i+1) >= xpRound(start) { out = append(out, r) }
			}
		} else {
			lv, err := evalArg(2); if err != nil { return xpVal{}, err }
			end := xpRound(start) + xpRound(xpToNumber(lv))
			for i, r := range s {
				pos := float64(i + 1)
				if pos >= xpRound(start) && pos < end { out = append(out, r) }
			}
		}
		return xpVal{kind: xvString, s: string(out)}, nil
	case "string-length":
		if len(args) > 1 { return xpVal{}, &xpFuncError{msg: "xpath: string-length function must have at most one parameter"} }
		var s string
		if len(args) == 0 { s = ctx.node.stringValue() } else { v, err := evalArg(0); if err != nil { return xpVal{}, err }; s = xpToString(v) }
		return xpVal{kind: xvNumber, n: float64(len([]rune(s)))}, nil
	case "normalize-space":
		if len(args) > 1 { return xpVal{}, &xpFuncError{msg: "xpath: normalize-space function must have at most one parameter"} }
		var s string
		if len(args) == 0 { s = ctx.node.stringValue() } else { v, err := evalArg(0); if err != nil { return xpVal{}, err }; s = xpToString(v) }
		return xpVal{kind: xvString, s: strings.Join(strings.Fields(s), " ")}, nil
	case "translate":
		if len(args) != 3 { return xpVal{}, &xpFuncError{msg: "xpath: translate function requires three arguments"} }
		var ss [3]string
		for i := 0; i < 3; i++ { v, err := evalArg(i); if err != nil { return xpVal{}, err }; ss[i] = xpToString(v) }
		from, to := []rune(ss[1]), []rune(ss[2])
		m := map[rune]rune{}
		del := map[rune]bool{}
		for i, fr := range from {
			if _, seen := m[fr]; seen || del[fr] { continue }
			if i < len(to) { m[fr] = to[i] } else { del[fr] = true }
		}
		var out []rune
		for _, r := range ss[0] {
			if del[r] { continue }
			if rep, ok := m[r]; ok { out = append(out, rep) } else { out = append(out, r) }
		}
		return xpVal{kind: xvString, s: string(out)}, nil
	case "sum":
		if len(args) != 1 { return xpVal{}, &xpFuncError{msg: "xpath: sum function requires one argument"} }
		ns, err := needNodes(0); if err != nil { return xpVal{}, err }
		sum := 0.0
		for _, n := range ns { sum += xpToNumber(nodesVal([]*xmlNode{n})) }
		return xpVal{kind: xvNumber, n: sum}, nil
	case "floor", "ceiling", "round":
		if len(args) != 1 { return xpVal{}, &xpFuncError{msg: fmt.Sprintf("xpath: %s function requires one argument", name)} }
		v, err := evalArg(0); if err != nil { return xpVal{}, err }
		num := xpToNumber(v)
		switch name {
		case "floor":
			return xpVal{kind: xvNumber, n: math.Floor(num)}, nil
		case "ceiling":
			return xpVal{kind: xvNumber, n: math.Ceil(num)}, nil
		default:
			// antchfx round() returns int
			return xpVal{kind: xvNumber, n: float64(int64(math.Round(num))), isInt: true}, nil
		}
	case "local-name", "namespace-uri", "name":
		if len(args) > 1 { return xpVal{}, &xpFuncError{msg: fmt.Sprintf("xpath: %s function must have at most one parameter", name)} }
		node := ctx.node
		if len(args) == 1 {
			ns, err := needNodes(0); if err != nil { return xpVal{}, err }
			if len(ns) == 0 { return xpVal{kind: xvString, s: ""}, nil }
			node = ns[0]
		}
		switch name {
		case "local-name":
			return xpVal{kind: xvString, s: node.localName()}, nil
		case "namespace-uri":
			return xpVal{kind: xvString, s: node.NamespaceURI}, nil
		default:
			return xpVal{kind: xvString, s: xpNodeName(node)}, nil
		}
	case "lang":
		if len(args) != 1 { return xpVal{}, &xpFuncError{msg: "xpath: lang function requires one argument"} }
		v, err := evalArg(0); if err != nil { return xpVal{}, err }
		lang := strings.ToLower(xpToString(v))
		for n := ctx.node; n != nil; n = ev.parentOf(n) {
			if n.Kind == kindElement {
				for _, a := range n.Attr {
					if a.Local == "lang" && a.Prefix == "xml" {
						lv := strings.ToLower(a.Value)
						return xpVal{kind: xvBool, b: lv == lang || strings.HasPrefix(lv, lang+"-")}, nil
					}
				}
			}
		}
		return xpVal{kind: xvBool, b: false}, nil
	}
	return xpVal{}, &xpFuncError{msg: fmt.Sprintf("not yet support this function %s()", name)}
}

func xpRound(n float64) float64 {
	if math.IsNaN(n) || math.IsInf(n, 0) { return n }
	return math.Floor(n + 0.5)
}

func xpNodeName(n *xmlNode) string {
	switch n.Kind {
	case kindDocument:
		return ""
	case kindElement, kindAttr:
		return n.qname()
	default:
		return n.Data
	}
}

// innerText for node-list (-e / node mode text) extraction.
func xpInnerText(n *xmlNode) string {
	switch n.Kind {
	case kindText, kindComment:
		return n.Data
	case kindAttr:
		return n.AttrValue
	case kindDocument, kindElement:
		var b strings.Builder
		var walk func(*xmlNode)
		walk = func(x *xmlNode) {
			for _, c := range x.Children {
				if c.Kind == kindText { b.WriteString(c.Data) } else { walk(c) }
			}
		}
		walk(n)
		return b.String()
	}
	return ""
}

func xpIsComparisonRoot(e xpExpr) bool {
	b, ok := e.(*xpBinary)
	if !ok { return false }
	switch b.op {
	case "=", "!=", "<", "<=", ">", ">=", "and", "or":
		return true
	}
	return false
}

// ---------- extraction entry points ----------

func extractXPath(r *bufio.Reader, w io.Writer, expr string, single bool, o *options) (err error) {
	defer func() {
		if rec := recover(); rec != nil {
			if rec == errNamespaceAxis {
				err = fmt.Errorf("XPath error: runtime error: invalid memory address or nil pointer dereference")
			} else {
				err = fmt.Errorf("XPath error: %v", rec)
			}
		}
	}()
	doc, perr := parseXMLDOM(r, getCharsetReader, false)
	if perr != nil {
		return perr
	}
	ev := newXpEval(doc)
	ast, perr := parseXPath(expr)
	ctx := xpCtx{node: doc, pos: 1, size: 1}

	formatNode := func(n *xmlNode) error {
		return formatXML(strings.NewReader(outputXML(n)), w, o.indentStr, o.colored)
	}
	printTextList := func(n *xmlNode) {
		fmt.Fprintln(w, strings.TrimSpace(xpInnerText(n)))
	}
	printTextAll := func(n *xmlNode) {
		fmt.Fprintln(w, strings.TrimSpace(n.stringValue()))
	}

	if !single && !o.node {
		// -x text mode.
		if perr != nil {
			return errors.New("unable to parse the XPath query")
		}
		if ferr := validateXPathFunctions(ast); ferr != nil {
			return errors.New("unable to parse the XPath query")
		}
		if xpIsNodeSetShaped(ast) && xpContainsNamespaceAxis(ast) {
			return errors.New("unable to parse the XPath query")
		}
		v, verr := ev.eval(ast, ctx)
		if verr != nil {
			return errors.New("unable to parse the XPath query")
		}
		switch v.kind {
		case xvNodes:
			for _, n := range v.nodes { printTextAll(n) }
			return nil
		case xvString:
			fmt.Fprintln(w, strings.TrimSpace(v.s))
			return nil
		case xvNumber:
			if v.isInt {
				return fmt.Errorf("unknown type error: %v", int64(v.n))
			}
			fmt.Fprintln(w, fmt.Sprintf("%.0f", v.n))
			return nil
		case xvBool:
			return fmt.Errorf("unknown type error: %v", v.b)
		}
		return nil
	}

	// Node-list mode: -e, or -x with -n.
	if perr != nil {
		return fmt.Errorf("XPath error: expression must evaluate to a node-set")
	}
	if ferr := validateXPathFunctions(ast); ferr != nil {
		return fmt.Errorf("XPath error: %w", ferr)
	}
	if xpIsNodeSetShaped(ast) && xpContainsNamespaceAxis(ast) {
		return fmt.Errorf("XPath error: undeclared variable in XPath expression: %s", expr)
	}
	var nodes []*xmlNode
	if single && xpIsComparisonRoot(ast) {
		v, verr := ev.eval(ast, ctx)
		if verr != nil {
			return fmt.Errorf("XPath error: %w", verr)
		}
		if xpToBool(v) {
			nodes = []*xmlNode{doc}
		}
	} else if xpIsNodeSetShaped(ast) {
		v, verr := ev.eval(ast, ctx)
		if verr != nil {
			if fe, ok := verr.(*xpFuncError); ok {
				return fmt.Errorf("XPath error: %w", fe)
			}
			return fmt.Errorf("XPath error: %w", verr)
		}
		if v.kind == xvNodes {
			nodes = v.nodes
		}
	} else {
		nodes = nil
	}
	if single && len(nodes) > 1 {
		nodes = nodes[:1]
	}
	// Keep document order stable for plain child/descendant results is
	// already the generation order; do not sort (antchfx preserves
	// axis/union generation order).
	_ = sort.Ints
	for _, n := range nodes {
		if o.node {
			if ferr := formatNode(n); ferr != nil {
				return ferr
			}
		} else {
			printTextList(n)
		}
	}
	return nil
}
