// ------------- selector AST -------------
type cssAttrSel struct {
	key, op, val, mod string
}
type cssPseudo struct {
	name string // lowercased
	arg  string
	// for :not a compound; for :has a selector group
	notArg *cssCompound
	hasArg []*cssSelector
}
type cssCompound struct {
	tag    string // "" (any), "*" or lowercased tag
	id     string
	hasID  bool
	class  []string
	attrs  []cssAttrSel
	pseudo []cssPseudo
}
type cssSelector struct {
	compounds   []*cssCompound
	combinators []string // between compounds: " ", ">", "+", "~"
}

var errCSSInvalid = fmt.Errorf("invalid selector")

// splitTopLevel splits on sep not inside [] () or quotes.
func cssSplitGroups(s string) ([]string, error) {
	var out []string
	depthP, depthB := 0, 0
	var quote byte
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote != 0 {
			if c == quote {
				quote = 0
			}
			continue
		}
		switch c {
		case '\'', '"':
			quote = c
		case '(':
			depthP++
		case ')':
			depthP--
			if depthP < 0 { return nil, errCSSInvalid }
		case '[':
			depthB++
		case ']':
			depthB--
			if depthB < 0 { return nil, errCSSInvalid }
		case ',':
			if depthP == 0 && depthB == 0 {
				out = append(out, s[start:i]); start = i + 1
			}
		}
	}
	if quote != 0 || depthP != 0 || depthB != 0 { return nil, errCSSInvalid }
	out = append(out, s[start:])
	return out, nil
}

type cssScanner struct {
	s string
	i int
}

func (sc *cssScanner) skipSpaces() bool {
	start := sc.i
	for sc.i < len(sc.s) && (sc.s[sc.i] == ' ' || sc.s[sc.i] == '\t' || sc.s[sc.i] == '\n' || sc.s[sc.i] == '\r' || sc.s[sc.i] == '\f') {
		sc.i++
	}
	return sc.i > start
}

func isCSSIdentStart(c byte) bool {
	return c == '_' || c == '-' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}
func isCSSIdentChar(c byte) bool {
	return isCSSIdentStart(c) || (c >= '0' && c <= '9')
}

func (sc *cssScanner) readIdent() (string, error) {
	var b strings.Builder
	first := true
	for sc.i < len(sc.s) {
		c := sc.s[sc.i]
		if c == '\\' {
			if sc.i+1 >= len(sc.s) { return "", errCSSInvalid }
			nc := sc.s[sc.i+1]
			if isHexDigit(nc) {
				j := sc.i + 1
				hex := ""
				for j < len(sc.s) && len(hex) < 6 && isHexDigit(sc.s[j]) { hex += string(sc.s[j]); j++ }
				if j < len(sc.s) && (sc.s[j] == ' ' || sc.s[j] == '\t' || sc.s[j] == '\n' || sc.s[j] == '\r' || sc.s[j] == '\f') { j++ }
				v, _ := strconv.ParseInt(hex, 16, 32)
				b.WriteRune(rune(v)); sc.i = j
			} else {
				b.WriteByte(nc); sc.i += 2
			}
			first = false
			continue
		}
		if first {
			if !isCSSIdentStart(c) && c != '-' { break }
			// A leading '-' must be followed by ident start or digit or '-'
		} else if !isCSSIdentChar(c) {
			break
		}
		b.WriteByte(c); sc.i++; first = false
	}
	if b.Len() == 0 { return "", errCSSInvalid }
	return b.String(), nil
}

func isHexDigit(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func (sc *cssScanner) readString() (string, error) {
	if sc.i >= len(sc.s) { return "", errCSSInvalid }
	q := sc.s[sc.i]
	if q != '\'' && q != '"' { return "", errCSSInvalid }
	sc.i++
	var b strings.Builder
	for sc.i < len(sc.s) {
		c := sc.s[sc.i]
		if c == q { sc.i++; return b.String(), nil }
		if c == '\\' && sc.i+1 < len(sc.s) {
			sc.i++
			b.WriteByte(sc.s[sc.i]); sc.i++
			continue
		}
		b.WriteByte(c); sc.i++
	}
	return "", errCSSInvalid
}

// readBalancedParens assumes current char is '('; returns contents.
func (sc *cssScanner) readParens() (string, error) {
	if sc.i >= len(sc.s) || sc.s[sc.i] != '(' { return "", errCSSInvalid }
	sc.i++
	start := sc.i
	depth := 1
	var quote byte
	for sc.i < len(sc.s) {
		c := sc.s[sc.i]
		if quote != 0 {
			if c == quote { quote = 0 }
			sc.i++; continue
		}
		switch c {
		case '\'', '"':
			quote = c
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 {
				content := sc.s[start:sc.i]
				sc.i++
				return content, nil
			}
		}
		sc.i++
	}
	return "", errCSSInvalid
}

func (sc *cssScanner) parseAttr() (cssAttrSel, error) {
	var a cssAttrSel
	// current '['
	sc.i++
	sc.skipSpaces()
	key, err := sc.readIdent()
	if err != nil { return a, err }
	a.key = strings.ToLower(key)
	sc.skipSpaces()
	if sc.i < len(sc.s) && sc.s[sc.i] == ']' {
		sc.i++; return a, nil
	}
	// operator
	if sc.i >= len(sc.s) { return a, errCSSInvalid }
	c := sc.s[sc.i]
	if c == '=' {
		a.op = "="; sc.i++
	} else if (c == '~' || c == '|' || c == '^' || c == '$' || c == '*') && sc.i+1 < len(sc.s) && sc.s[sc.i+1] == '=' {
		a.op = string(c) + "="; sc.i += 2
	} else {
		return a, errCSSInvalid
	}
	sc.skipSpaces()
	if sc.i < len(sc.s) && (sc.s[sc.i] == '\'' || sc.s[sc.i] == '"') {
		v, err := sc.readString(); if err != nil { return a, err }
		a.val = v
	} else {
		// identifier or number-ish value
		start := sc.i
		for sc.i < len(sc.s) && (isCSSIdentChar(sc.s[sc.i])) { sc.i++ }
		if sc.i == start { return a, errCSSInvalid }
		a.val = sc.s[start:sc.i]
	}
	sc.skipSpaces()
	// optional modifier i/s
	if sc.i < len(sc.s) && sc.s[sc.i] != ']' {
		m, err := sc.readIdent(); if err != nil { return a, err }
		if strings.EqualFold(m, "i") { a.mod = "i" } else if strings.EqualFold(m, "s") { a.mod = "s" } else { return a, errCSSInvalid }
		sc.skipSpaces()
	}
	if sc.i >= len(sc.s) || sc.s[sc.i] != ']' { return a, errCSSInvalid }
	sc.i++
	return a, nil
}

func (sc *cssScanner) parseCompound() (*cssCompound, error) {
	comp := &cssCompound{tag: ""}
	parsedAny := false
	// type or universal
	if sc.i < len(sc.s) && sc.s[sc.i] == '*' {
		// namespace *| or |* invalid
		if sc.i+1 < len(sc.s) && sc.s[sc.i+1] == '|' { return nil, errCSSInvalid }
		comp.tag = "*"; sc.i++; parsedAny = true
	} else if sc.i < len(sc.s) && (isCSSIdentStart(sc.s[sc.i])) {
		id, err := sc.readIdent(); if err != nil { return nil, err }
		if sc.i < len(sc.s) && sc.s[sc.i] == '|' { return nil, errCSSInvalid }
		comp.tag = strings.ToLower(id); parsedAny = true
	} else if sc.i < len(sc.s) && sc.s[sc.i] == '|' {
		return nil, errCSSInvalid
	}
	for sc.i < len(sc.s) {
		c := sc.s[sc.i]
		switch c {
		case '#':
			sc.i++; id, err := sc.readIdent(); if err != nil { return nil, err }
			comp.id = id; comp.hasID = true; parsedAny = true
		case '.':
			sc.i++; id, err := sc.readIdent(); if err != nil { return nil, err }
			comp.class = append(comp.class, id); parsedAny = true
		case '[':
			at, err := sc.parseAttr(); if err != nil { return nil, err }
			comp.attrs = append(comp.attrs, at); parsedAny = true
		case ':':
			if sc.i+1 < len(sc.s) && sc.s[sc.i+1] == ':' { return nil, errCSSInvalid }
			sc.i++
			name, err := sc.readIdent(); if err != nil { return nil, err }
			ps := cssPseudo{name: strings.ToLower(name)}
			if sc.i < len(sc.s) && sc.s[sc.i] == '(' {
				content, err := sc.readParens(); if err != nil { return nil, err }
				ps.arg = content
				// Validate/process special pseudos now.
				switch ps.name {
				case "not":
					inner := &cssScanner{s: strings.TrimSpace(content)}
					c2, err := inner.parseCompound(); if err != nil { return nil, err }
					inner.skipSpaces()
					if inner.i != len(inner.s) { return nil, errCSSInvalid }
					ps.notArg = c2
				case "has":
					trimmed := strings.TrimSpace(content)
					if strings.HasPrefix(trimmed, ">") || strings.HasPrefix(trimmed, "+") || strings.HasPrefix(trimmed, "~") { return nil, errCSSInvalid }
					grp, err := parseCSSSelector(trimmed); if err != nil { return nil, err }
					ps.hasArg = grp
				}
			} else {
				// pseudos requiring args
				switch ps.name {
				case "nth-child", "nth-last-child", "nth-of-type", "nth-last-of-type", "not", "has", "lang", "contains", "containsown":
					return nil, errCSSInvalid
				}
			}
			if !cssPseudoKnown(ps) { return nil, errCSSInvalid }
			comp.pseudo = append(comp.pseudo, ps); parsedAny = true
		default:
			goto done
		}
	}
done:
	if !parsedAny { return nil, errCSSInvalid }
	return comp, nil
}

func cssPseudoKnown(ps cssPseudo) bool {
	switch ps.name {
	case "first-child", "last-child", "only-child", "first-of-type", "last-of-type", "only-of-type",
		"empty", "root", "link", "visited", "checked", "enabled", "disabled", "input",
		"nth-child", "nth-last-child", "nth-of-type", "nth-last-of-type",
		"not", "has", "lang", "contains", "containsown":
		// Validate arguments for nth/lang.
		if strings.HasPrefix(ps.name, "nth-") {
			if _, _, err := parseNth(ps.arg); err != nil { return false }
		}
		if ps.name == "lang" {
			a := strings.TrimSpace(ps.arg)
			if a == "" { return false }
			for _, r := range a {
				if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z') { return false }
			}
		}
		return true
	}
	return false
}

func parseCSSSelectorGroup(s string) ([]*cssSelector, error) {
	parts, err := cssSplitGroups(s)
	if err != nil { return nil, err }
	var out []*cssSelector
	for _, part := range parts {
		sel, err := parseCSSOne(strings.TrimSpace(part))
		if err != nil { return nil, err }
		out = append(out, sel)
	}
	if len(out) == 0 { return nil, errCSSInvalid }
	return out, nil
}

func parseCSSSelector(s string) ([]*cssSelector, error) { return parseCSSSelectorGroup(s) }

func parseCSSOne(s string) (*cssSelector, error) {
	if strings.TrimSpace(s) == "" { return nil, errCSSInvalid }
	sc := &cssScanner{s: s}
	sel := &cssSelector{}
	pendingComb := ""
	for {
		hadSpace := sc.skipSpaces()
		if sc.i >= len(sc.s) { break }
		c := sc.s[sc.i]
		if c == '>' || c == '+' || c == '~' {
			if len(sel.compounds) == 0 { return nil, errCSSInvalid }
			pendingComb = string(c); sc.i++; sc.skipSpaces()
			if sc.i >= len(sc.s) { return nil, errCSSInvalid }
			c2 := &cssCompound{}
			parsed, err := sc.parseCompound(); if err != nil { return nil, err }
			c2 = parsed
			sel.combinators = append(sel.combinators, pendingComb)
			sel.compounds = append(sel.compounds, c2)
			pendingComb = ""
			continue
		}
		if len(sel.compounds) > 0 {
			if !hadSpace { return nil, errCSSInvalid }
			sel.combinators = append(sel.combinators, " ")
		}
		comp, err := sc.parseCompound(); if err != nil { return nil, err }
		sel.compounds = append(sel.compounds, comp)
	}
	if len(sel.compounds) == 0 { return nil, errCSSInvalid }
	return sel, nil
}

func parseNth(arg string) (int, int, error) {
	s := strings.ReplaceAll(strings.ToLower(strings.TrimSpace(arg)), " ", "")
	s = strings.ReplaceAll(s, "\t", "")
	switch s {
	case "odd":
		return 2, 1, nil
	case "even":
		return 2, 0, nil
	}
	if !strings.Contains(s, "n") {
		v, err := strconv.Atoi(s)
		if err != nil { return 0, 0, errCSSInvalid }
		return 0, v, nil
	}
	parts := strings.SplitN(s, "n", 2)
	aStr, bStr := parts[0], parts[1]
	var a int
	switch aStr {
	case "", "+":
		a = 1
	case "-":
		a = -1
	default:
		v, err := strconv.Atoi(aStr); if err != nil { return 0, 0, errCSSInvalid }
		a = v
	}
	b := 0
	if bStr != "" {
		v, err := strconv.Atoi(bStr); if err != nil { return 0, 0, errCSSInvalid }
		b = v
	}
	return a, b, nil
}

func nthMatches(pos, a, b int) bool {
	if a == 0 { return pos == b }
	diff := pos - b
	if a > 0 {
		return diff >= 0 && diff%a == 0
	}
	return diff <= 0 && diff%a == 0
}

// ------------- matching -------------
func cssMatchCompound(n *html.Node, comp *cssCompound) bool {
	if n.Type != html.ElementNode { return false }
	if comp.tag != "" && comp.tag != "*" && !strings.EqualFold(n.Data, comp.tag) { return false }
	if comp.hasID {
		v, ok := htmlAttr(n, "id"); if !ok || v != comp.id { return false }
	}
	for _, cl := range comp.class {
		v, ok := htmlAttr(n, "class"); if !ok { return false }
		found := false
		for _, f := range strings.Fields(v) { if f == cl { found = true; break } }
		if !found { return false }
	}
	for _, at := range comp.attrs {
		v, ok := htmlAttr(n, at.key)
		if !ok { return false }
		if at.op == "" { continue }
		val := at.val
		vv := v
		if at.mod == "i" { vv = strings.ToLower(vv); val = strings.ToLower(val) }
		switch at.op {
		case "=":
			if vv != val { return false }
		case "~=":
			if val == "" { return false }
			found := false
			for _, f := range strings.Fields(vv) { if f == val { found = true; break } }
			if !found { return false }
		case "|=":
			if vv != val && !strings.HasPrefix(vv, val+"-") { return false }
		case "^=":
			if val == "" || !strings.HasPrefix(vv, val) { return false }
		case "$=":
			if val == "" || !strings.HasSuffix(vv, val) { return false }
		case "*=":
			if val == "" || !strings.Contains(vv, val) { return false }
		}
	}
	for _, ps := range comp.pseudo {
		if !cssMatchPseudo(n, ps) { return false }
	}
	return true
}

func cssIsDisabled(n *html.Node) bool {
	cats := map[string]bool{"button": true, "input": true, "select": true, "textarea": true, "optgroup": true, "option": true, "fieldset": true}
	if !cats[n.Data] { return false }
	if _, ok := htmlAttr(n, "disabled"); ok { return true }
	// ancestor fieldset[disabled], except descendants of its first legend child
	for anc := n.Parent; anc != nil; anc = anc.Parent {
		if anc.Type == html.ElementNode && anc.Data == "fieldset" {
			if _, ok := htmlAttr(anc, "disabled"); ok {
				// find first legend element child
				var legend *html.Node
				for c := anc.FirstChild; c != nil; c = c.NextSibling {
					if c.Type == html.ElementNode && c.Data == "legend" { legend = c; break }
				}
				if legend != nil {
					// is n inside legend?
					inside := false
					for x := n; x != nil; x = x.Parent { if x == legend { inside = true; break } }
					if inside { continue }
				}
				return true
			}
		}
	}
	return false
}

func cssMatchPseudo(n *html.Node, ps cssPseudo) bool {
	switch ps.name {
	case "root":
		return n.Parent != nil && n.Parent.Type == html.DocumentNode
	case "empty":
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			if c.Type == html.ElementNode { return false }
			if c.Type == html.TextNode && strings.TrimSpace(c.Data) != "" { return false }
		}
		return true
	case "first-child", "last-child", "only-child", "first-of-type", "last-of-type", "only-of-type",
		"nth-child", "nth-last-child", "nth-of-type", "nth-last-of-type":
		sibs := elementSiblings(n)
		if sibs == nil { sibs = []*html.Node{n} }
