func parseContainsArg(arg string) string {
	a := strings.TrimSpace(arg)
	if len(a) >= 2 {
		if (a[0] == '\'' && a[len(a)-1] == '\'') || (a[0] == '"' && a[len(a)-1] == '"') {
			return a[1 : len(a)-1]
		}
	}
	return a
}

func cssMatchSelectorAt(n *html.Node, sel *cssSelector, idx int) bool {
	if !cssMatchCompound(n, sel.compounds[idx]) { return false }
	if idx == 0 { return true }
	comb := sel.combinators[idx-1]
	switch comb {
	case ">":
		p := parentElement(n)
		return p != nil && cssMatchSelectorAt(p, sel, idx-1)
	case " ":
		for p := parentElement(n); p != nil; p = parentElement(p) {
			if cssMatchSelectorAt(p, sel, idx-1) { return true }
		}
		return false
	case "+":
		p := prevElementSibling(n)
		return p != nil && cssMatchSelectorAt(p, sel, idx-1)
	case "~":
		for p := prevElementSibling(n); p != nil; p = prevElementSibling(p) {
			if cssMatchSelectorAt(p, sel, idx-1) { return true }
		}
		return false
	}
	return false
}

func cssQueryAll(doc *html.Node, group []*cssSelector) []*html.Node {
	var out []*html.Node
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.ElementNode {
			for _, sel := range group {
				if cssMatchSelectorAt(n, sel, len(sel.compounds)-1) {
					out = append(out, n); break
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling { walk(c) }
	}
	walk(doc)
	return out
}

func extractCSS(r *bufio.Reader, w io.Writer, o *options) error {
	doc, err := html.Parse(r)
	if err != nil {
		return err
	}
	group, serr := parseCSSSelectorGroup(o.query)
	if serr != nil {
		return nil // invalid selectors silently yield no results
	}
	nodes := cssQueryAll(doc, group)
	for _, n := range nodes {
		if o.attr != "" {
			v, _ := htmlAttr(n, o.attr)
			fmt.Fprintln(w, v)
		} else if o.node {
			var buf bytes.Buffer
			_ = html.Render(&buf, n)
			if err := formatHTML(bytes.NewReader(buf.Bytes()), w, o.indentStr, o.colored); err != nil {
				return err
			}
		} else {
			fmt.Fprintln(w, strings.TrimSpace(htmlInnerTextRaw(n)))
		}
	}
	return nil
}
